import{_ as o,I as a,g as e,j as l}from"./chunks/framework.CjoWWfVe.js";const m=JSON.parse('{"title":"Модуль «Амбассадор»","description":"Продвижение, генерация умных ссылок, QR-коды на чеках, учет кампаний и ИИ-помощник маркетолога.","frontmatter":{"title":"Модуль «Амбассадор»","description":"Продвижение, генерация умных ссылок, QR-коды на чеках, учет кампаний и ИИ-помощник маркетолога.","order":17},"headers":[],"relativePath":"ru/docs/spaces/ambassador.md","filePath":"ru/docs/spaces/ambassador.md"}'),t={name:"ru/docs/spaces/ambassador.md"};function i(s,r,n,d,c,g){return a(),e("div",null,[...r[0]||(r[0]=[l('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку ОмниКрафт ЕРП сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="🚀-модуль-«амбассадор»-маркетинг-и-партнерство" tabindex="-1">🚀 Модуль «Амбассадор» (Маркетинг и Партнёрство) <a class="header-anchor" href="#🚀-модуль-«амбассадор»-маркетинг-и-партнерство" aria-label="Permalink to &quot;🚀 Модуль «Амбассадор» (Маркетинг и Партнёрство)&quot;">​</a></h1><p><strong>Амбассадор</strong> — это бесплатный системный инструмент, решающий сразу две ключевые задачи мастера и предпринимателя:</p><ol><li><strong>Партнёрский доход в экосистеме ОмниКрафт ЕРП:</strong> Рекомендация программы коллегам с получением бессрочной комиссии и оплатой подписок накопленными баллами.</li><li><strong>Продвижение собственного дела:</strong> Удобный конструктор ссылок, учет рекламных кампаний и встроенный искусственный интеллект для продвижения ваших собственных изделий, цифровых выкроек, обучающих курсов или программ.</li></ol><hr><h2 id="🏗️-1-вкладка-«конструктор»-создание-умных-ссылок-и-qr-кодов" tabindex="-1">🏗️ 1. Вкладка «Конструктор»: Создание умных ссылок и QR-кодов <a class="header-anchor" href="#🏗️-1-вкладка-«конструктор»-создание-умных-ссылок-и-qr-кодов" aria-label="Permalink to &quot;🏗️ 1. Вкладка «Конструктор»: Создание умных ссылок и QR-кодов&quot;">​</a></h2><p>В конструкторе вы можете за пару кликов подготовить ссылку под любую рекламную публикацию или офлайн-мероприятие:</p><ul><li><strong>Выбор назначения ссылки:</strong><ul><li><em>Партнёрка ОмниКрафт ЕРП:</em> Создает ссылку с вашим персональным кодом (например, <code>INV-XXXX-XXXX</code>).</li><li><em>Мой продукт / Внешний сайт:</em> Позволяет указать адрес вашего собственного сайта, интернет-магазина или группы и автоматически добавить рекламные метки источников.</li></ul></li><li><strong>Выбор площадки:</strong> Telegram, ВКонтакте, Хабр / VC.ru, Пикабу, Ярмарка Мастеров, Офлайн / Выставки или любая другая площадка.</li><li><strong>Генерация и экспорт:</strong> Программа мгновенно формирует готовую ссылку и <strong>QR-код</strong>, который можно сохранить для печати на визитках, баннерах или упаковке.</li></ul><h3 id="🧾-органическии-рост-водянои-знак-на-электронных-чеках" tabindex="-1">🧾 Органический рост: Водяной знак на электронных чеках <a class="header-anchor" href="#🧾-органическии-рост-водянои-знак-на-электронных-чеках" aria-label="Permalink to &quot;🧾 Органический рост: Водяной знак на электронных чеках&quot;">​</a></h3><p>Включите пункт <strong>«Размещать QR-код на чеках»</strong>, и на каждом электронном чеке при продаже товаров в кассовом терминале будет аккуратно печататься блок с вашим персональным QR-кодом. Передавая чек покупателю, вы органически привлекаете новых пользователей без лишних затрат времени.</p><hr><h2 id="📋-2-вкладка-«кампании-crm-»-учет-и-контроль-публикации" tabindex="-1">📋 2. Вкладка «Кампании (CRM)»: Учет и контроль публикаций <a class="header-anchor" href="#📋-2-вкладка-«кампании-crm-»-учет-и-контроль-публикации" aria-label="Permalink to &quot;📋 2. Вкладка «Кампании (CRM)»: Учет и контроль публикаций&quot;">​</a></h2><p>Все созданные ссылки автоматически сохраняются в единый реестр кампаний. Здесь вы можете вести полноценный учет вашей маркетинговой активности:</p><ul><li><strong>Статусы публикаций:</strong> Отслеживайте жизненный цикл каждой идеи (<code>Идея</code> ➔ <code>В работе</code> ➔ <code>Опубликовано</code> ➔ <code>Завершено</code> / <code>Отклонено</code>).</li><li><strong>Учет договоренностей:</strong> Фиксируйте выделенный бюджет, контактные данные блогеров или администраторов каналов, а также фактические ссылки на вышедшие посты и статьи.</li><li><strong>Быстрый переход к генерации текста:</strong> Нажатие на значок волшебной палочки в строке кампании сразу открывает ИИ-помощника для подготовки текста именно под эту публикацию.</li></ul><hr><h2 id="🤖-3-вкладка-«ии-маркетолог»-создание-текстов-и-подбор-стратегии" tabindex="-1">🤖 3. Вкладка «ИИ-Маркетолог»: Создание текстов и подбор стратегии <a class="header-anchor" href="#🤖-3-вкладка-«ии-маркетолог»-создание-текстов-и-подбор-стратегии" aria-label="Permalink to &quot;🤖 3. Вкладка «ИИ-Маркетолог»: Создание текстов и подбор стратегии&quot;">​</a></h2><p>Встроенный помощник на базе искусственного интеллекта помогает составлять качественные продающие материалы и подбирать нестандартные каналы продвижения:</p><ul><li><strong>Форматы материалов:</strong><ul><li><em>Разработка Стратегии (AI Growth):</em> ИИ анализирует ваш продукт и предлагает список конкретных площадок, аудиторных зацепок и план продвижения.</li><li><em>Посты для социальных сетей (ВКонтакте, Telegram):</em> Яркие тексты с эмодзи и призывом к действию.</li><li><em>Статьи-кейсы (Хабр, VC.ru, Пикабу):</em> Экспертные лонгриды и истории личного опыта.</li><li><em>Личные сообщения (Питчи):</em> Вежливые и убедительные предложения о сотрудничестве для блогеров и партнеров.</li><li><em>Электронные рассылки:</em> Структурированные письма для клиентской базы.</li></ul></li><li><strong>Защита ссылок:</strong> Искусственный интеллект не искажает адреса — программа автоматически и безошибочно подставляет вашу точную ссылку в готовый текст.</li><li><strong>Экспорт для внешних помощников:</strong> Кнопка «Экспорт» формирует стандартизированный файл контекста для передачи автономным цифровым ассистентам.</li><li><strong>Live Discovery:</strong> Умная подгрузка списка актуальных моделей нейросетей при вводе ключа (нет необходимости вручную искать и прописывать идентификаторы новых моделей).</li><li><strong>Безопасность ключей:</strong> Ваши персональные ключи доступа к нейросетям надежно зашифрованы средствами операционной системы (Windows DPAPI).</li></ul><hr><h2 id="💰-4-партнерская-программа-и-магазин-вознаграждении" tabindex="-1">💰 4. Партнерская программа и Магазин вознаграждений <a class="header-anchor" href="#💰-4-партнерская-программа-и-магазин-вознаграждении" aria-label="Permalink to &quot;💰 4. Партнерская программа и Магазин вознаграждений&quot;">​</a></h2><p>При привлечении коллег в ОмниКрафт ЕРП действует <strong>бессрочная привязка (Lifetime)</strong>: вы получаете процент со всех покупок и продлений привлеченного пользователя.</p><h3 id="шкала-начислении" tabindex="-1">Шкала начислений: <a class="header-anchor" href="#шкала-начислении" aria-label="Permalink to &quot;Шкала начислений:&quot;">​</a></h3><ul><li>🥉 <strong>Партнёр</strong> (1–3 продажи в месяц) ➔ Комиссия <strong>20%</strong></li><li>🥈 <strong>Мастер</strong> (4–9 продаж в месяц) ➔ Комиссия <strong>30%</strong></li><li>👑 <strong>Легенда</strong> (10+ продаж в месяц) ➔ Комиссия <strong>50%</strong></li></ul><h3 id="🎁-использование-баланса" tabindex="-1">🎁 Использование баланса: <a class="header-anchor" href="#🎁-использование-баланса" aria-label="Permalink to &quot;🎁 Использование баланса:&quot;">​</a></h3><p>Накопленные рубли отображаются на дашборде. Нажав кнопку <em>«Списать бонусы»</em>, вы можете оплатить ими:</p><ul><li>Продление стандартной подписки.</li><li>Бессрочный переход на версию ПРО.</li><li>Покупку специализированных модулей (например, модуля работы с выкройками).</li></ul>',26)])])}const u=o(t,[["render",i]]);export{m as __pageData,u as default};
